#include <stdlib.h>
#include <string.h>
#include "sign_batch.h"

int sign_batch(const char** messages, size_t n, char** out_json) {
    // Implementation: sign each message and return JSON array
    // [{"msg": "...", "sig": "..."}, ...]
}

void free_json(char* json) {
    free(json);
